class ParticleGroup {

  static populate(aGroup){
    for (let i = 0; i < aGroup.amount; i++){
      aGroup.container.push(new Particle(Math.round(Math.random()*width / (unit / TWO_PI)) * unit/TWO_PI, Math.round(Math.random()*height / (unit/TWO_PI)) *unit/TWO_PI, aGroup.sizeRange[0]/2+random(aGroup.sizeRange[0])));
    }
  }

  constructor(color, amount, sizeRange = [0.1, 0.3]){
    this.color = color;
    this.sizeRange = sizeRange;
    this.amount = amount;
    this.container = [];
    this.populated=false;
  }

  update(){
    if (this.populated==false){
      ParticleGroup.populate(this);
      this.populated=true;
    }
    w.pull(this);
    w2.pull(this);

    for (let particles of this.container){
      fill(this.color);
      particles.move();
      particles.checkEdge();
      particles.display();
    }
  }
  }

/////////////////////////////////////////////////////////////////////////

class Particle {
  constructor(x, y, size) {
    this.dir = createVector(0, 0);
    this.vel = createVector(size/2, size/2);
    this.pos = createVector(x, y);
    this.speed = random([size/2, -size/2]);
    this.size = size;
    this.angle = TWO_PI;
    this.noiseScale = noiseScale;
    this.well=false;
  }

  move() {
    //this.noiseScale+=cos(tickly/nums)
    this.angle = noise((-0.5*width+this.pos.x) / this.noiseScale, (-0.5*height+this.pos.y )/ this.noiseScale);
    this.angle *= (TWO_PI);

    this.pos.y += this.speed*(Math.cos(this.angle));
    this.pos.x += this.speed*(Math.sin(this.angle));
  }

  checkEdge() {

    if (this.pos.x < 0 || this.pos.x > width ||this.pos.y < 0 || this.pos.y > height) {
      this.pos.x = round(random(width) / (unit/TWO_PI)) * unit/TWO_PI;
      this.pos.y = round(random(height) / (unit/TWO_PI)) * unit/TWO_PI;
      this.speed*= -1;
    }

  }

  display() {
    ellipse(this.pos.x, this.pos.y, this.size );
  }
}

//////////////////////////////////////////////////////////////////////

class Well{

constructor(x, y, strength, diameter){
this.x=x;
this.y=y;
this.mag = strength;
this.d=diameter;
this.maxDist = (((strength)+diameter))*PI;
this.angle=1;
this.speed=1;
}

move(){

this.angle = noise(0.5*this.x / noiseScale, 0.5*this.y / noiseScale);
    this.angle *= (TWO_PI);

    this.y += (this.d/PI)*(Math.cos(this.angle));
    this.x += (this.d/PI)*(Math.sin(this.angle));
  }

  checkEdge() {

    if (this.x < 0 || this.x > width || this.y < 0 || this.y > height) {
      this.x = round(random(width) / (unit/TWO_PI)) * unit/TWO_PI;
      this.y = round(random(height) / (unit/TWO_PI)) * unit/TWO_PI;
			this.speed*=-1
    }
    }


  pull(pGroup){
    for (let p of pGroup.container){
  let d = dist(this.x, this.y, p.pos.x, p.pos.y);
      if(abs(d) <= abs(this.maxDist)){
        p.noiseScale=((d*this.angle)*atan((p.noiseScale/this.mag)));
         p.speed-=((d/p.size*p.angle/p.noiseScale)*sin((d*this.mag)));
      } else {
				p.speed=Math.sign(p.speed)*p.size/2;
			}
        fill(pGroup.color);
      p.move();
      p.checkEdge();
      p.display();

  }
  }
}

/////////////////////////////////////////////////////////////////////

function rCol(alpha = 4 /*4+Math.random()*12*/) {
  return [Math.random() * 255, Math.random() * 255, Math.random() * 255, alpha];
}

